import argparse
import json
import os
import subprocess
import threading
import time
from collections import deque
from typing import List, Dict, Any

def evaluate_expression(expr: str) -> int:
    try:
        return eval(expr)
    except:
        return 0

def process_command(command: str, line_num: int) -> Dict[str, Any]:
    result = {"line": line_num, "command": command, "output": "", "exit_code": 0}
    placeholders = []
    current = ""
    for i, char in enumerate(command):
        if char == "{{":
            if current:
                placeholders.append(current)
                current = ""
            if i + 1 < len(command) and command[i+1] == "}":
                placeholders.append(command[i:i+2])
                if i + 2 < len(command):
                    current = command[i+2:]
        elif char == "}}":
            if current:
                placeholders.append(current)
                current = ""
    if current:
        placeholders.append(current)

    for i, placeholder in enumerate(placeholders):
        if "{{" in placeholder and "}}" in placeholder:
            expr = placeholder[2:-1]
            value = evaluate_expression(expr)
            command = command.replace(placeholder, str(value))

    try:
        result["command"] = command
        process = subprocess.Popen(
            command.split(),
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE,
            text=True,
            bufsize=1,
            universal_newlines=True
        )
        stdout, stderr = process.communicate()
        result["output"] = stdout + stderr
        result["exit_code"] = process.returncode
    except Exception as e:
        result["output"] = str(e)
        result["exit_code"] = -1
    return result

def run_commands_with_concurrency(
    commands: List[str],
    concurrency: int,
    rate: float,
    results: List[Dict[str, Any]]
) -> None:
    active_threads = 0
    last_start_time = time.time()
    command_queue = deque(commands)
    result_queue = deque(results)

    def worker():
        nonlocal active_threads
        while True:
            if not command_queue:
                break
            if active_threads >= concurrency:
                time.sleep(0.001)
                continue
            if time.time() - last_start_time >= 1.0 / rate:
                last_start_time = time.time()
                active_threads = min(concurrency, active_threads - 1)
            cmd = command_queue.popleft()
            result = process_command(cmd, len(results) + len(command_queue) + 1)
            result_queue.append(result)
            active_threads += 1
            time.sleep(0.001)

    threads = []
    for _ in range(concurrency):
        t = threading.Thread(target=worker)
        t.start()
        threads.append(t)

    for t in threads:
        t.join()

    while command_queue:
        time.sleep(0.001)

    while result_queue:
        results.append(result_queue.popleft())

def main():
    parser = argparse.ArgumentParser(description="Process commands with placeholders and run them concurrently.")
    parser.add_argument("input_file", help="Path to the file containing commands")
    parser.add_argument("--concurrency", type=int, default=1, help="Maximum number of concurrent commands")
    parser.add_argument("--rate", type=float, default=1.0, help="Maximum commands per second")
    args = parser.parse_args()

    with open(args.input_file, "r") as f:
        lines = [line.strip() for line in f if line.strip()]

    results = []
    run_commands_with_concurrency(lines, args.concurrency, args.rate, results)

    for result in results:
        print(json.dumps(result))

if __name__ == "__main__":
    main()

