import argparse
import json
import subprocess
import re
import threading
import queue
from collections import defaultdict

def process_command(command, line_num):
    def replace_placeholders(cmd):
        def replacer(match):
            expr = match.group(1)
            try:
                result = eval(expr)
                return str(result)
            except:
                return match.group(0)
        return re.sub(r'\{\{(.*?)\}\}', replacer, cmd)

    processed_cmd = replace_placeholders(command)
    try:
        result = subprocess.run(processed_cmd, shell=True, check=True, text=True, capture_output=True)
        output = result.stdout + result.stderr
        return {
            'line': line_num,
            'command': processed_cmd,
            'output': output,
            'exit_code': result.returncode
        }
    except subprocess.CalledProcessError as e:
        output = e.stderr + e.stdout
        return {
            'line': line_num,
            'command': processed_cmd,
            'output': output,
            'exit_code': e.returncode
        }

def worker(command_queue, results_queue, concurrency):
    while True:
        try:
            command = command_queue.get_nowait()
            result = process_command(command, command_queue.qsize() + 1)
            results_queue.put(result)
        except queue.Empty:
            break

def main():
    parser = argparse.ArgumentParser()
    parser.add_argument('file_path', help='Path to the text file containing commands')
    parser.add_argument('--concurrency', type=int, default=1, help='Maximum number of concurrent commands')
    args = parser.parse_args()

    with open(args.file_path, 'r') as file:
        commands = [line.strip() for line in file if line.strip()]

    command_queue = queue.Queue()
    results_queue = queue.Queue()

    for i, cmd in enumerate(commands, 1):
        command_queue.put(cmd)

    threads = []
    for _ in range(min(args.concurrency, len(commands))):
        t = threading.Thread(target=worker, args=(command_queue, results_queue, args.concurrency))
        t.start()
        threads.append(t)

    for t in threads:
        t.join()

    results = []
    while not results_queue.empty():
        results.append(results_queue.get())

    for result in results:
        print(json.dumps(result))

if __name__ == '__main__':
    main()
